        return "", -1

    if line[start] != '"':
        # Field is not quoted
        end = line.find(',', start)
        if end == -1:
            end = len(line)
        field = line[start:end]
        next_start = end + 1
    else:
        # Field is quoted
        end = line.find('"', start + 1)
        while end != -1 and end + 1 < len(line) and line[end + 1] == '"':
            end = line.find('"', end + 2)
        if end == -1:
            raise ValueError("Unmatched quote in field")
        field = line[start + 1:end].replace('""', '"')
        next_start = end + 2

    return field, next_start
```

