        if line[i] == '"':
            if i > 0 and line[i-1] == '"':
                field.append('"')
                i += 1
            else:
                in_quotes = not in_quotes
        elif line[i] == ',' and not in_quotes:
            break
        else:
            field.append(line[i])
        i += 1

    if in_quotes:
        raise ValueError("Unclosed quote in field")

    return ''.join(field), i
