    if start >= len(line):
        return ('', -1)

    if line[start] != '"':
        end = line.find(',', start)
        if end == -1:
            field = line[start:]
            next_start = len(line)
        else:
            field = line[start:end]
            next_start = end + 1
    else:
        end = line.find('"', start + 1)
        while end != -1 and end < len(line) - 1 and line[end + 1] == '"':
            end = line.find('"', end + 2)
        if end == -1:
            raise ValueError("Unmatched quotes")
        field = line[start + 1:end].replace('""', '"')
        next_start = end + 2

    return field, next_start
